<?php
namespace App\Interfaces\Http\Controllers\Api\V1\CarrierOperations;use App\Application\Audit\AuditWriter;use App\Domain\CarrierOperations\AuthorityChecker;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class CarrierOperationsController{
public function createAuthority(Request$r,AuditWriter$audit){$d=$r->validate(['carrier_id'=>'required|uuid|exists:carriers,id','partner_id'=>'required|uuid|exists:partners,id','agreement_number'=>'required|string|max:80|unique:delegated_authority_agreements,agreement_number','effective_from'=>'required|date','effective_until'=>'required|date|after:effective_from','permitted_lines'=>'required|array|min:1','permitted_lines.*'=>'in:AUTOMOBILE,HEALTH,TRAVEL,PROPERTY','max_policy_premium_minor'=>'required|integer|min:0','max_claim_authority_minor'=>'required|integer|min:0','territories'=>'required|array|min:1']);$id=(string)Str::uuid();DB::table('delegated_authority_agreements')->insert([...$d,'id'=>$id,'status'=>'DRAFT','permitted_lines'=>json_encode($d['permitted_lines']),'territories'=>json_encode($d['territories']),'created_at'=>now(),'updated_at'=>now()]);$audit->record('delegated_authority.created','delegated_authority_agreement',$id,['agreement_number'=>$d['agreement_number']]);return response()->json(['data'=>['id'=>$id,'status'=>'DRAFT']],201);}
public function approveAuthority(Request$r,string$agreement,AuditWriter$audit){$d=$r->validate(['reason'=>'required|string|min:20|max:2000']);$updated=DB::table('delegated_authority_agreements')->where(['id'=>$agreement,'status'=>'DRAFT'])->update(['status'=>'ACTIVE','approved_by_carrier'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);abort_unless($updated,409);$audit->record('delegated_authority.approved','delegated_authority_agreement',$agreement);return response()->json(['data'=>['id'=>$agreement,'status'=>'ACTIVE']]);}
public function checkAuthority(Request$r,string$agreement,AuthorityChecker$checker){$d=$r->validate(['line_code'=>'required|string','premium_minor'=>'required|integer|min:0','territory'=>'required|string','effective_at'=>'required|date']);$a=DB::table('delegated_authority_agreements')->where('id',$agreement)->first();abort_unless($a,404);$decision=$checker->check(['status'=>$a->status,'effective_from'=>$a->effective_from,'effective_until'=>$a->effective_until,'permitted_lines'=>json_decode($a->permitted_lines,true),'max_policy_premium_minor'=>$a->max_policy_premium_minor,'territories'=>json_decode($a->territories,true)],$d['line_code'],$d['premium_minor'],$d['territory'],new \DateTimeImmutable($d['effective_at']));return response()->json(['data'=>$decision]);}
public function acknowledgeBordereau(Request$r,string$bordereau,AuditWriter$audit){$d=$r->validate(['carrier_reference'=>'required|string|max:160','decision'=>'required|in:ACKNOWLEDGED,REJECTED','notes'=>'required|string|min:20|max:2000']);$row=DB::table('bordereaux')->where('id',$bordereau)->where('status','SUBMITTED')->first();abort_unless($row,409);DB::table('bordereaux')->where('id',$bordereau)->update(['status'=>$d['decision'],'carrier_reference'=>$d['carrier_reference'],'updated_at'=>now()]);$audit->record('bordereau.carrier_decided','bordereau',$bordereau,['decision'=>$d['decision'],'carrier_reference'=>$d['carrier_reference']]);return response()->json(['data'=>['id'=>$bordereau,'status'=>$d['decision']]]);}}
